def mcq(i,q,key,distr,why,source,objective,operation,code=None):
    opts=[key]+distr
    target=(i-1)%4
    shift=(-target)%4
    opts=opts[shift:]+opts[:shift]
    row={"id":f"M2L2-{i:03d}","question":q,"options":opts,"correctIndex":opts.index(key),"expectedAnswer":key,"explanation":why,"source":source,"objective":objective,"operation":operation}
    if code: row["stimulusCode"]=code
    return row

